this.currentDataLoadId++;
const loadId = this.currentDataLoadId;
const limitPerColumn = 20; // Scalable limit per column

try {
    this.isLoadingData = true;
    this.kanbanColumns = []; // Reset view

    // --- 1. Fetch Pipeline Stages (The Columns) ---
    const { entities: stages } = await this.entityService.getAllEntities({
        entity: "pipelinestage",
        query: `pipelineId_eq=${pipelineId}`,
        limit: 1000
    });

    if (loadId !== this.currentDataLoadId) return;

    // Initialize column state
    this.kanbanColumns = (stages ?? []).map(stage => ({
        ...stage,
        deals: [],
        totalDealsInStage: "00",
        currentPage: 1,
        isLoadingDeals: true,
        hasNextPage: true,
        isEditingPipelineStageName: false,
        originalName: stage.name
    })).toSorted((a, b) => a.order - b.order);

    // --- 2. Fetch Deals for each column concurrently ---
    const dealLoadPromises = this.kanbanColumns.map(column =>
        this.loadDealsForColumn(column, loadId, limitPerColumn)
    );

    await Promise.all(dealLoadPromises);
    this.stageColumn.attachScrollListeners();

} catch (error) {
    console.error("Error loading Kanban board:", error);
    this.notificationService.notify({
        alertType: "error",
        alertDescription: "Failed to load pipeline stages.",
        dismissIn: 5_000
    });
} finally {
    if (loadId === this.currentDataLoadId) {
        this.isLoadingData = false;
    }
}

try {
        column.isLoadingDeals = true;
        let query = `pipelineStageId_eq=${column.pipelineStageId}`;
        if (this.currentFilter.query) {
            query += `&${this.currentFilter.query}`;
        }

        const { entities: deals, totalFiltered, hasNextPage } = await this.entityService.getAllEntities({
            entity: "opportunity",
            query: query,
            page: column.currentPage,
            limit: limit,
        });

        if (loadId !== this.currentDataLoadId) return;

        column.deals = [...column.deals, ...deals];
        column.hasNextPage = hasNextPage;

        this.updateColumnCounter(column);

    } catch (error) {
        console.error(`Error loading deals for stage ${column.name}:`, error);
    } finally {
        column.isLoadingDeals = false;
    }

if (queryString === null) {
    this.currentFilter = {
        ...this.currentFilter,
        query: '',
        filtersApplied: [{ property: null, operation: null, value: "" }]
    };
} else if (queryString !== undefined) {
    this.currentFilter.query = queryString;
}

const activePipelineId = this.currentPipeline.pipelineId;
await this.loadKanbanData(activePipelineId);

try {
    const METHOD = "POST";
    const entityType = "pipelinestage";

    const { general: { name, order } } = form;

    const newStage = {
        name: name,
        order: order,
        pipelineId: pipelineId ?? this.currentPipeline.pipelineId
    };

    const response = await this.dataService.sendData(
        entityType,
        METHOD,
        newStage
    );

    if (response.result !== "OK") {
        throw new Error(response.message || "Failed to update deal stage.");
    }

    this.isAddingPipelineStage = false;
    this.utilityService.clearForm(form);
    await this.loadKanbanData(this.currentPipeline.pipelineId);

} catch (error) {
    console.error("Backend update failed:", error);
    this.notificationService.notify({
        alertType: "error",
        alertDescription: error.message,
        dismissIn: 5_000
    });
}

if (!stage || !stage.pipelineStageId) {
    this.notificationService.notify({
        alertType: "error",
        alertDescription: "Pipeline Stage ID is missing or invalid.",
        dismissIn: 5_000
    });
    return;
}

const { pipelineStageId, name, order, createdOn, modifiedOn, tenantId, pipelineId } = stage;
const entityType = "pipelinestage"

try {
    this.isDeletingPipelineStage = true;

    const cleanStageForDisplay = { 
        pipelineStageId, 
        name, 
        order, 
        createdOn, 
        modifiedOn, 
        tenantId, 
        pipelineId 
    };

    const options = {
        displayName: name,
        modalData: this.utilityService.formatEntityForDisplay(cleanStageForDisplay)
    };

    const result = await this.dataService.deleteData(
        entityType,
        pipelineStageId,
        options
    );

    if (result?.result !== 'cancel') {
        this.loadKanbanData(this.currentPipeline.pipelineId);
    }

} catch (e) {
    console.error("Failed to delete pipeline stage: ", e);
    this.notificationService.notify({
        alertType: "error",
        alertDescription: e.message,
        dismissIn: 5_000
    });
} finally {
    this.isDeletingPipelineStage = false;
}

const sourceCol = this.kanbanColumns.find(c => c.pipelineStageId === sourceStageId);
const dealIndex = sourceCol.deals.findIndex(d => d.opportunityId === opportunityId);

if (dealIndex > -1) {
    const [deal] = sourceCol.deals.splice(dealIndex, 1);

    targetColumn.deals.unshift(deal);

    this.updateColumnCounter(sourceCol);
    this.updateColumnCounter(targetColumn);
}

try {
    const METHOD = "PUT";
    const entityType = "opportunity";

    const requestBody = {
        opportunityId: opportunityId,
        pipelineStageId: newStageId,
    };

    const response = await this.dataService.sendData(
        entityType,
        METHOD,
        requestBody
    );

    if (response.result !== "OK") {
        throw new Error(response.message || "Failed to update deal stage.");
    }

    // Optional: Sync the Side Panel if the moved deal is the one being viewed
    if (this.currentEntity && this.currentEntity.opportunityId === opportunityId) {
        this.currentEntity.pipelineStageId = newStageId;
        // Optionally refresh side panel data to get the new 'modifiedOn' timestamp
        // await this.refreshSidePanel(opportunityId);
    }

} catch (error) {
    console.error("Backend update failed:", error);
    this.notificationService.notify({
        alertType: "error",
        alertDescription: error.message,
        dismissIn: 5_000
    });
    await this.loadKanbanData(this.currentPipeline.pipelineId);

}

const localCount = column.deals.length;

if (column.hasNextPage) {
    // If the server has more pages, the total is at least 20+
    column.totalDealsInStage = `${localCount}+`;
} else {
    // If we've reached the end of the server data, 
    // the local array length is the true total.
    if (localCount < 10) {
        column.totalDealsInStage = `0${localCount}`;
    } else {
        column.totalDealsInStage = localCount;
    }
}

try {
