    }

} catch (error) {
    console.error("Backend update failed:", error);
    this.notificationService.notify({
        alertType: "error",
        alertDescription: error.message,
        dismissIn: 5_000
    });
    await this.loadKanbanData(this.currentPipeline.pipelineId);
}

this.currentFilter.column = "";
this.currentFilter.operation = "";
this.currentFilter.target = "";
this.currentFilter.query = "";

this.currentFilter.filtersApplied = [
    {
        property: null,
        operation: null,
        value: null
    }
];

this.currentFilter.sortsApplied = [
    {
        property: null,
        order: "ASC"
    }
];

const container = document.querySelector('.pipeline-container');
if (container) container.classList.remove('is-dragging-deal', 'is-reordering-stages');

if (event && event.currentTarget) {
    event.currentTarget.classList.remove('deal-drag-over', 'stage-drag-over', 'stage-dragging');
}

const allStages = document.querySelectorAll('.stage-column');
allStages.forEach(stage => {
    stage.classList.remove('deal-drag-over', 'stage-drag-over', 'stage-dragging');
});

const allCards = document.querySelectorAll('.deal-card');
allCards.forEach(card => {
    card.classList.remove('dragging', 'drag-placeholder');
});

this.currentPipeline = null;
this.selectedDeal = null;
this.isLoadingData = false;
this.isSendingData = false;
this.isAddingPipelineStage = false;
this.isDeletingPipelineStage = false;

this.selectedDealDetails = [];
this.kanbanColumns = [];

this.clearKanbanFilter();

