const dragData = {
    opportunityId: deal.opportunityId,
    sourceStageId: stage.pipelineStageId
};
event.dataTransfer.setData("application/json", JSON.stringify(dragData));
event.dataTransfer.effectAllowed = "move";

const container = document.querySelector('.pipeline-container');
container.classList.add('is-dragging-deal');

const target = event.target;
target.classList.add('dragging');

this.$timeout(() => {
    target.classList.add('drag-placeholder');
}, 0);

// 1. Select all the scrollable card-list containers
const columnElements = document.querySelectorAll('.card-list') ?? [];

if (columnElements.length > 0) {
    columnElements.forEach((el, index) => {
        // We use a named function so we can remove it later if needed
        el.addEventListener('scroll', (event) => {
            this.stageColumn.onScroll(event, this.kanbanColumns[index]);
        });
    });
} else {
    this.$timeout(this.stageColumn.attachScrollListeners, 100);
}

const columnElements = document.querySelectorAll('card-list');
columnElements.forEach((el) => {
    el.removeEventListener('scroll', this.handleColumnScroll);
});

const element = event.target;

// Calculate distance from bottom
// scrollHeight: Total height of content
// scrollTop: How much has been scrolled
// clientHeight: Height of the visible container
const threshold = 10;
const isAtBottom = element.scrollHeight - element.scrollTop <= element.clientHeight + threshold;

// Only load if we are at the bottom, not already loading, and there's more data to fetch
if (isAtBottom && !column.isLoadingDeals && column.hasNextPage) {
    this.stageColumn.onColumnScrollEnd(column);
}

// If the user clicked a deal-card or inside a card-list, 
// ignore the stage drag start.
if (event.target.closest('.card-list')) {
    return;
}

const container = document.querySelector('.pipeline-container');
container.classList.add('is-reordering-stages');

event.dataTransfer.setData("application/stage-id", stage.pipelineStageId);
event.dataTransfer.setData("application/stage-order", stage.order);
event.target.classList.add('stage-dragging');

event.preventDefault();
const types = event.dataTransfer.types;

if (types.includes("application/json")) {
    event.currentTarget.classList.add('deal-drag-over');
} else if (types.includes("application/stage-id")) {
    event.currentTarget.classList.add('stage-drag-over');
}

event.preventDefault();
this.clearDragStyles(event);

const types = event.dataTransfer.types;

// 1. Handle Deal Drop
if (types.includes("application/json")) {
    const rawData = event.dataTransfer.getData("application/json");
    const { opportunityId, sourceStageId } = JSON.parse(rawData);

    if (sourceStageId !== targetColumn.pipelineStageId) {
        this.moveDealLocally(opportunityId, sourceStageId, targetColumn);
        await this.updateDealStage(opportunityId, targetColumn.pipelineStageId);
    }
}
// 2. Handle Stage Drop
else if (types.includes("application/stage-id")) {
    const draggedStageId = event.dataTransfer.getData("application/stage-id");
    const draggedStageOrder = parseInt(event.dataTransfer.getData("application/stage-order"));

    if (draggedStageOrder !== targetColumn.order) {
        // newOrder is based on the targetColumn's current position
        await this.updateStageOrder(draggedStageId, targetColumn.order);
        await this.loadKanbanData(this.currentPipeline.pipelineId);
    }
}

